class A:
 @property
 def x(self):
  print('get')
  return 4
 @x.setter
 def x(self,value): self.saved=value
 @x.deleter
 def x(self): print('delete')
a=A()
setattr(a,'x',8)
print(getattr(a,'x'),a.saved)
delattr(a,'x')

class A:
 @property
 def x(self): raise AttributeError('missing')
a=A()
print(getattr(a,'x',8),hasattr(a,'x'))

class A:
 @property
 def x(self): raise ValueError('bad')
print(hasattr(A(),'x'))

class A:
